import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.BG8d4IEm.js";const _=JSON.parse('{"title":"wechat_config","description":"","frontmatter":{"title":"wechat_config","tags":"wechat_config","birth":"2017-06-06T00:00:00.000Z","modified":"2017-06-06T00:00:00.000Z"},"headers":[],"relativePath":"projects/wechat/wechat_config.md","filePath":"projects/wechat/wechat_config.md"}'),o={name:"projects/wechat/wechat_config.md"};function r(c,a,h,n,s,d){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="wechat-config" tabindex="-1">wechat_config <a class="header-anchor" href="#wechat-config" aria-label="Permalink to &quot;wechat_config&quot;">​</a></h1><p><strong>前言:讲解微信配置项</strong></p><hr><h1 id="常见配置" tabindex="-1">常见配置 <a class="header-anchor" href="#常见配置" aria-label="Permalink to &quot;常见配置&quot;">​</a></h1><h2 id="域名调用" tabindex="-1">域名调用 <a class="header-anchor" href="#域名调用" aria-label="Permalink to &quot;域名调用&quot;">​</a></h2><ol><li>公众号设置-&gt; 功能设置</li><li>设置域名将文件保存到项目根路径即可</li></ol><h2 id="更改微信管理员" tabindex="-1">更改微信管理员 <a class="header-anchor" href="#更改微信管理员" aria-label="Permalink to &quot;更改微信管理员&quot;">​</a></h2><ol><li>进入 <code>设置-&gt; 安全中心 -&gt; 管理员微信号</code></li></ol><p>让原始管理员扫描二维码后,新管理重新扫描二维码即可.</p><p>原始管理员的确定,是在微信公众平台填写注册信息时. 确定的.</p><ol start="2"><li><p>后台更改 微信 appid 配置和数据库</p></li><li><p>微信基本配置修改服务器地址</p></li></ol><ul><li>url 填写这是微信向公众号推送消息的地址</li><li>token 微信和公众号初始握手标志</li><li>EncodingAESKey 随机生成即可</li></ul><ol start="4"><li>若在获取 access_token 是出现失败逻辑 先根据 <a href="https://mp.weixin.qq.com/wiki?id=mp1421140183&amp;highline=40164" target="_blank" rel="noreferrer">access_token</a> 获取失败原因</li></ol><h2 id="_40164" tabindex="-1">40164 <a class="header-anchor" href="#_40164" aria-label="Permalink to &quot;40164&quot;">​</a></h2><p>ip 没有权限调用该接口设置如下</p><ol><li>点击基本配置</li><li>ip 白名单 添加接口 ip 即可</li></ol><h2 id="修改公众号名称" tabindex="-1">修改公众号名称 <a class="header-anchor" href="#修改公众号名称" aria-label="Permalink to &quot;修改公众号名称&quot;">​</a></h2><ol><li>登录微信公众号-&gt;公众号设置</li><li>微信号-&gt;设置微信号修改即可</li></ol><blockquote><p>微信公众号名字一年只能修改一次,这你改的是微信号 不是微信公众号的名称</p></blockquote><h2 id="微信公众号昵称修改" tabindex="-1">微信公众号昵称修改 <a class="header-anchor" href="#微信公众号昵称修改" aria-label="Permalink to &quot;微信公众号昵称修改&quot;">​</a></h2><p>只有年审的时候才可以重新修改. 在认证过程中会在问一次.</p><p>详情参见 <a href="https://kf.qq.com/faq/120911VrYVrA160722nURN7r.html" target="_blank" rel="noreferrer">公众号修改流程</a></p><h2 id="重置微信公众号" tabindex="-1">重置微信公众号 <a class="header-anchor" href="#重置微信公众号" aria-label="Permalink to &quot;重置微信公众号&quot;">​</a></h2><ul><li>菜单,自定义菜单关闭即可</li><li>接口推送 基本设置关闭即可</li></ul>',24)])])}const f=e(o,[["render",r]]);export{_ as __pageData,f as default};
